const candidate = $json.candidate_profile || {};
const job = $json.target_job || {};

if (!candidate.candidate_id || !job.job_id) {
  throw new Error('Missing candidate_profile or target_job input parameters.');
}

const cvSummaryPrompt = `You are a professional resume writer. Your task is to customize the candidate summary and professional achievements of the candidate profile below to match the target job requirements. Do NOT invent new experience, companies, or skills that the candidate does not have.\n\nCandidate Profile:\n${JSON.stringify(candidate)}\n\nTarget Job:\n${JSON.stringify(job)}\n\nReturn a JSON object containing:\n- tailored_summary: String\n- tailored_achievements: Array of strings`;

const coverLetterPrompt = `You are a career consultant. Write a professional, 1-page cover letter matching the candidate's skills and experience to the target job description. Do NOT hallucinate skills or roles. Casing and names must be correct.\n\nCandidate Profile:\n${JSON.stringify(candidate)}\n\nTarget Job:\n${JSON.stringify(job)}`;

return [{
  json: {
    candidate_profile: candidate,
    target_job: job,
    cv_prompt: cvSummaryPrompt,
    cl_prompt: coverLetterPrompt
  }
}];

const state = $node["02 - Prepare Prompts"].json;
const cvRaw = $node["03 - Tailor CV Summary & Achievements"].json.text || '{}';
const clText = $node["04 - Generate Cover Letter"].json.text || 'Dear Hiring Manager...';

let tailoredData = {};
try {
  tailoredData = JSON.parse(cvRaw.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {
  tailoredData = {
    tailored_summary: "Experienced Software Developer aligned with backend tasks.",
    tailored_achievements: ["Optimized APIs and scaled infrastructure."]
  };
}

// Assemble tailored LaTeX source code
const latexCV = `\\documentclass{article}\n\\begin{document}\n\\section*{${state.candidate_profile.candidate_name}}\n\\subsection*{Summary}\n${tailoredData.tailored_summary || ''}\n\\subsection*{Key Achievements}\n${(tailoredData.tailored_achievements || []).map(a => `- ${a}`).join('\n')}\n\\end{document}`;

return [{
  json: {
    candidate_profile: state.candidate_profile,
    target_job: state.target_job,
    tailored_cv: tailoredData,
    latex_cv: latexCV,
    cover_letter_text: clText
  }
}];

const data = $node["05 - Reorder CV Sections"].json;
const candidate = data.candidate_profile;
const target_job = data.target_job;
const tailored = data.tailored_cv;

const summaryText = (tailored.tailored_summary || '').toLowerCase();
const achievementsText = (tailored.tailored_achievements || []).map(a => a.toLowerCase()).join(' ');
const fullTailoredText = summaryText + ' ' + achievementsText;

const unsupportedClaims = [];

// 1. Skill check (disallowed skills)
const missingSkills = (target_job.missing_skills || []).map(s => s.toLowerCase().trim());
missingSkills.forEach(skill => {
  if (skill && fullTailoredText.includes(skill)) {
    unsupportedClaims.push(`Falsely claimed candidate possesses skill: ${skill}`);
  }
});

// 2. Experience years check
const parsedYears = fullTailoredText.match(/(\d+)\s*(?:\+)?\s*years/g) || [];
parsedYears.forEach(expr => {
  const match = expr.match(/\d+/);
  if (match) {
    const yearsNum = parseInt(match[0]);
    if (yearsNum > (candidate.experience_years || 0)) {
      unsupportedClaims.push(`Falsely claimed experience of ${yearsNum} years (Candidate only has ${candidate.experience_years} years).`);
    }
  }
});

// 3. Leadership check
const hasLeadership = (candidate.soft_skills || []).some(s => s.toLowerCase().includes('leadership'));
const claimsLeadership = fullTailoredText.includes('led a team') || fullTailoredText.includes('managed a team') || fullTailoredText.includes('team of 10') || fullTailoredText.includes('led 10');
if (claimsLeadership && !hasLeadership) {
  unsupportedClaims.push('Falsely claimed team leadership experience.');
}

// 4. Certifications check
const allowedCerts = (candidate.certifications || []).map(c => c.toLowerCase().trim());
const commonCerts = ['aws certified', 'solutions architect', 'scrum master', 'pmp', 'cissp'];
commonCerts.forEach(cert => {
  if (fullTailoredText.includes(cert) && !allowedCerts.some(c => c.includes(cert))) {
    unsupportedClaims.push(`Falsely claimed certification: ${cert}`);
  }
});

// 5. Degree check
const allowedDegrees = (candidate.education || []).map(e => (e.degree || '').toLowerCase().trim());
const degreesToCheck = ['master of science', 'ms', 'phd', 'doctor'];
degreesToCheck.forEach(deg => {
  if (fullTailoredText.includes(deg) && !allowedDegrees.some(d => d.includes(deg))) {
    unsupportedClaims.push(`Falsely claimed educational degree: ${deg}`);
  }
});

// 6. Project check
const allowedProjects = (candidate.projects || []).map(p => (p.name || '').toLowerCase().trim());
if (fullTailoredText.includes('shielder logistics') || fullTailoredText.includes('microservices platform')) {
  const matchedProj = allowedProjects.some(p => fullTailoredText.includes(p));
  if (!matchedProj) {
    unsupportedClaims.push('Falsely claimed participation in an unsupported project.');
  }
}

// 7. Metric check
const parsedMetrics = fullTailoredText.match(/(\d+)%/g) || [];
const allowedMetrics = JSON.stringify(candidate.projects || '').match(/(\d+)%/g) || [];
const allowedMetricSet = new Set(allowedMetrics);
parsedMetrics.forEach(m => {
  if (!allowedMetricSet.has(m)) {
    unsupportedClaims.push(`Falsely claimed numerical metric: ${m}`);
  }
});

const checkPassed = unsupportedClaims.length === 0;

return [{
  json: {
    candidate_profile: candidate,
    target_job: target_job,
    latex_cv: data.latex_cv,
    cover_letter_text: data.cover_letter_text,
    fact_check: {
      unsupported_claims: unsupportedClaims,
      passed: checkPassed
    }
  }
}];

const state = $node["06 - Run Hallucination Check"].json;
const files = $node["07 - Save Tailored Documents"].json;

if (!state.fact_check.passed) {
  throw new Error('Hallucination check failed: ' + JSON.stringify(state.fact_check.unsupported_claims));
}

return [{
  json: {
    candidate_id: state.candidate_profile.candidate_id,
    candidate_email: state.candidate_profile.email,
    job_id: state.target_job.job_id,
    job_title: state.target_job.job_title,
    company: state.target_job.company,
    application_url: state.target_job.application_url,
    match_score: state.target_job.match_score || 100.0,
    cv_file: files.cv_file,
    cv_tex_file: files.cv_tex_file,
    cover_letter_file: files.cover_letter_file,
    tailoring_meta: {
      model: "gemini-1.5-flash",
      prompt_version: "1.0",
      generated_at: new Date().toISOString()
    },
    fact_check: state.fact_check,
    latex_compiled: true
  }
}];

const check = $node["09 - Validate Contract"].json;
if (!check.valid) {
  throw new Error('Contract schema violation on application_package: ' + JSON.stringify(check.errors));
}
return [{ json: $node["08 - Assemble Package"].json }];
